 matches RQC:RQC-129 (0.73); FAM:SF-CHT-039 auto_addresses_question RQC:RQC-129"], "attributes": {"observed_research_question": "Series-level AVOID share vs winning (talent confound)", "auto_outcome_status": "untestable", "observed_hypothesis": "Higher AVOID share predicts losing, independent of team quality.", "observed_result": "Game-level rho=-0.19 p=0.008 (inflated n, team-quality confound). Series-level rho=-0.26 p=0.07 (n=50, underpowered; ~80 series needed for p<0.05). Low AVOID-share bin 52.6% vs 25-50% bin 37.0%.", "auto_failure_mechanism": "A_unanswerable (question not answerable with the data or design)", "observed_failure_evidence": "Series n=50 p=0.07; still confounded by team quality (OKC disciplined and good).", "observed_sample_and_power": "n=50 series; stated need ~80 for p<0.05", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "inconclusive"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:confounding"}, {"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:CONFOUNDING"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}]}], "n_results": 10}

